// The icon site. It renders the package straight from packages/react/src
// (generated by scripts/generate.mjs), so it shows exactly what ships.
//
//   pnpm site          dev server
//   pnpm site:build    static build in site/dist
import { fileURLToPath } from "node:url"
import { defineConfig } from "vite"

const here = (path) => fileURLToPath(new URL(path, import.meta.url))

export default defineConfig({
  root: here("."),
  base: "./",
  esbuild: { jsx: "automatic" },
  resolve: {
    alias: [
      { find: /^@quick-ui\/icons\/sharp$/, replacement: here("../packages/react/src/sharp/index.ts") },
      { find: /^@quick-ui\/icons$/, replacement: here("../packages/react/src/index.ts") },
    ],
  },
  build: { outDir: here("dist"), emptyOutDir: true, chunkSizeWarningLimit: 8000 },
})
